actions.script:
const L = (text) => ec.l10n.localize(text)
const nowMillis = Number(String(ec.user.nowTimestamp))
const lists = Array.from(ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListTypeEnumId', 'not-equals', 'MAILBOX')
        .orderBy('contactListName').list())
const archived = (list) => list.archivedDate != null && Number(String(list.archivedDate)) <= nowMillis
listOptions = lists.sort((a, b) => (archived(a) ? 1 : 0) - (archived(b) ? 1 : 0)).map((list) => ({key: list.contactListId,
    text: (list.contactListName || list.contactListId) + (archived(list) ? ' · ' + L('archived') : ''), archived: archived(list)}))
const enums = (typeId) => Array.from(ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', typeId).orderBy('sequenceNum').useCache(true).list())
        .map((item) => ({key: item.enumId, text: item.description || item.enumId}))
purposeOptions = enums('PartyConsentPurpose')
sourceOptions = enums('PartyConsentSource')
const statuses = (typeId) => Array.from(ec.entity.find('moqui.basic.StatusItem').condition('statusTypeId', typeId).orderBy('sequenceNum').useCache(true).list())
        .map((item) => ({key: item.statusId, text: item.description || item.statusId}))
statusOptions = statuses('ContactListParty').filter((item) => ['CLPT_ACCEPTED', 'CLPT_PENDING', 'CLPT_UNSUBS_PENDING', 'CLPT_UNSUBSCRIBED'].includes(item.key))
        .map((item) => ({key: item.key, text: L('List') + ': ' + item.text}))
        .concat(statuses('PartyConsent').map((item) => ({key: item.key, text: L('Consent') + ': ' + item.text})))

changed = false
ec.service.sync().name('ironstone.comms.ConsentServices.check#ConsentAdmin').parameter('need', true).call()
if (ec.message.hasError()) return
ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'view'}).call()
if (ec.message.hasError()) return
if (subscribe) {
    const out = ec.service.sync().name('mantle.party.ConsentServices.subscribe#ContactListParty').parameters({contactListId: contactListId,
        partyId: partyId, contactMechId: contactMechId || null, sourceEnumId: 'PcsStaff', evidenceText: evidenceText || null}).call()
    if (ec.message.hasError()) return
    statusId = out.statusId; changed = !!out.changed
} else {
    const out = ec.service.sync().name('mantle.party.ConsentServices.unsubscribe#ContactListParty').parameters({contactListId: contactListId,
        partyId: partyId, contactMechId: contactMechId || null, sourceEnumId: 'PcsStaff', evidenceText: evidenceText || null, confirmed: true}).call()
    if (ec.message.hasError()) return
    statusId = out.statusId; changed = (out.changedList || []).length > 0
}

unsubscribedCount = 0; unchangedCount = 0; failedPartyIdList = []
ec.service.sync().name('ironstone.comms.ConsentServices.check#ConsentAdmin').parameter('need', true).call()
if (ec.message.hasError()) return
const ids = []
for (const id of Array.from(new Set(Array.from(partyIdList || []).map((value) => String(value).trim()).filter((value) => value)))) {
    const access = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: id}).call()
    if (access?.visible) ids.push(id); else failedPartyIdList.push(id)
}
if (!ids.length) return
const out = ec.service.sync().name('mantle.party.ConsentServices.unsubscribe#ContactListParties').parameters({contactListId: contactListId,
    partyIdList: ids, sourceEnumId: 'PcsStaff', evidenceText: evidenceText || null, confirmed: true}).call()
if (ec.message.hasError()) return
unsubscribedCount = (out.unsubscribedCount || 0) + (out.pendingCount || 0)
unchangedCount = out.unchangedCount || 0
failedPartyIdList = failedPartyIdList.concat(Array.from(out.failedPartyIdList || []))

ec.service.sync().name('ironstone.comms.ConsentServices.check#ConsentAdmin').parameter('need', true).call()
if (ec.message.hasError()) return
const access = ec.service.sync().name('ironstone.commons.ContactServices.check#ContactAccess').parameters({partyId: partyId, need: 'view'}).call()
if (ec.message.hasError()) return
const history = ec.service.sync().name('mantle.party.ConsentServices.get#PartyConsentHistory').parameters({partyId: partyId, pageNoLimit: true}).call()
if (ec.message.hasError()) return
const quote = (value) => {
    const text = value == null ? '' : String(value)
    return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text
}
const iso = (value) => value == null || value === '' ? '' : new Date(Number(String(value))).toISOString()
const name = ec.resource.expand('PartyFullNameTemplate', '', access.party).trim() || partyId
const lines = [['Party ID', 'Name', 'When', 'Purpose', 'Status', 'Address', 'List', 'Source', 'Evidence', 'Comments', 'Recorded By'].map(quote).join(',')]
for (const row of Array.from(history.historyList || [])) lines.push([partyId, name, iso(row.consentDate), row.purposeDescription, row.statusDescription,
    row.addressText, row.contactListName, row.sourceDescription, row.evidenceText, row.comments, row.userName].map(quote).join(','))
csvText = lines.join('\r\n') + '\r\n'
fileName = `consent-history-${String(partyId).replace(/[^A-Za-z0-9_-]/g, '_')}.csv`
